/* Uc seviyeli akordeon menu + kaldigin yerden devam (ES3, OS 5 uyumlu)
   MENU = [ {t:'Ust', g:[ {t:'Alt', i:[ 'etiket' | [baslik,href] | {s:'Alt-alt', i:[[baslik,href],..]} ]} ]} ] */
var MENU_ROOT = '';

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function fileOf(h) { var a = String(h).split('/'); return a[a.length - 1]; }
function curFile() {
  var p = '';
  try { p = location.pathname || ''; } catch (e) {}
  return fileOf(p) || 'index.html';
}
function isSub(it) { return typeof it === 'object' && it.s !== undefined; }
function isLink(it) { return typeof it === 'object' && it.s === undefined; }

/* {a,b,c,item}: c = alt-alt baslik sirasi (yoksa -1) */
function findLink(test) {
  var a, b, c, j, it, sub;
  for (a = 0; a < MENU.length; a++) {
    for (b = 0; b < MENU[a].g.length; b++) {
      for (c = 0; c < MENU[a].g[b].i.length; c++) {
        it = MENU[a].g[b].i[c];
        if (isLink(it)) {
          if (test(it)) { return { a: a, b: b, c: -1, item: it }; }
        } else if (isSub(it)) {
          for (j = 0; j < it.i.length; j++) {
            if (test(it.i[j])) { return { a: a, b: b, c: c, item: it.i[j] }; }
          }
        }
      }
    }
  }
  return null;
}
function findByFile(file) { return findLink(function (it) { return fileOf(it[1]) === file; }); }
function findByHref(href) { return findLink(function (it) { return it[1] === href; }); }

function getY() {
  return window.pageYOffset ||
    (document.documentElement && document.documentElement.scrollTop) ||
    (document.body && document.body.scrollTop) || 0;
}

function resumeHtml(cur) {
  var last = sget('last'), f, y;
  if (!last) { return ''; }
  f = findByHref(last);
  if (!f || fileOf(f.item[1]) === cur) { return ''; }
  y = parseInt(sget('y'), 10) || 0;
  return '<div class="resume"><b>Kald&#305;&#287;&#305;n yer:</b><br>' +
    '<a href="' + MENU_ROOT + f.item[1] + '" onclick="sset(\'resume\',\'1\');return true;">' +
    '&#9654; ' + esc(f.item[0]) + '</a>' + (y > 100 ? '<br><small>(sayfan&#305;n i&ccedil;inden devam eder)</small>' : '') + '</div>';
}

function linkLi(it, cur) {
  return '<li' + (fileOf(it[1]) === cur ? ' class="cur"' : '') + '><a href="' + MENU_ROOT + it[1] + '">' + esc(it[0]) + '</a></li>';
}

function buildMenu(cur, oa, ob, oc) {
  var h = '', a, b, c, j, it, grp, open;
  h += '<div class="mhead"><a href="' + MENU_ROOT + 'index.html">Ana sayfa</a></div>';
  h += resumeHtml(cur);
  for (a = 0; a < MENU.length; a++) {
    h += '<div class="mtop' + (a === oa ? ' open' : '') + '" id="mt' + a + '">';
    h += '<a href="#" class="mtt" onclick="return mtop(' + a + ');">' +
         '<span class="t-plus">[+]</span><span class="t-minus">[&minus;]</span> ' + esc(MENU[a].t) + '</a>';
    h += '<div class="mtbody">';
    for (b = 0; b < MENU[a].g.length; b++) {
      grp = MENU[a].g[b];
      h += '<div class="mg' + ((a === oa && b === ob) ? ' open' : '') + '" id="mg' + a + '_' + b + '">';
      h += '<a href="#" class="mgt" onclick="return mgrp(' + a + ',' + b + ');">' +
           '<span class="m-plus">[+]</span><span class="m-minus">[&minus;]</span> ' + esc(grp.t) + '</a>';
      h += '<ul class="mlist">';
      for (c = 0; c < grp.i.length; c++) {
        it = grp.i[c];
        if (typeof it === 'string') {
          h += '<li class="mlabel">' + esc(it) + '</li>';
        } else if (isSub(it)) {
          open = (a === oa && b === ob && c === oc);
          h += '<li class="msli"><div class="ms' + (open ? ' open' : '') + '" id="ms' + a + '_' + b + '_' + c + '">';
          h += '<a href="#" class="mst" onclick="return msub(' + a + ',' + b + ',' + c + ');">' +
               '<span class="s-plus">[+]</span><span class="s-minus">[&minus;]</span> ' + esc(it.s) + '</a>';
          h += '<ul class="msl">';
          for (j = 0; j < it.i.length; j++) { h += linkLi(it.i[j], cur); }
          h += '</ul></div></li>';
        } else {
          h += linkLi(it, cur);
        }
      }
      h += '</ul></div>';
    }
    h += '</div></div>';
  }
  return h;
}

function isOpen(id) { var el = document.getElementById(id); return !!(el && hasClass(el, 'open')); }

function saveOpen() {
  var a, b, c, oa = -1, ob = -1, oc = -1, g;
  for (a = 0; a < MENU.length; a++) { if (isOpen('mt' + a)) { oa = a; } }
  if (oa > -1) {
    for (b = 0; b < MENU[oa].g.length; b++) { if (isOpen('mg' + oa + '_' + b)) { ob = b; } }
    if (ob > -1) {
      g = MENU[oa].g[ob];
      for (c = 0; c < g.i.length; c++) { if (isSub(g.i[c]) && isOpen('ms' + oa + '_' + ob + '_' + c)) { oc = c; } }
    }
  }
  sset('open', oa + ',' + ob + ',' + oc);
}

function closeAll(prefix, n, suffix) {
  var i, el;
  for (i = 0; i < n; i++) { el = document.getElementById(prefix + i + (suffix || '')); if (el) { removeClass(el, 'open'); } }
}

/* her seviyede ayni anda tek bolum acik */
function mtop(a) {
  var was = isOpen('mt' + a);
  closeAll('mt', MENU.length);
  if (!was) { addClass(document.getElementById('mt' + a), 'open'); }
  saveOpen();
  return false;
}
function mgrp(a, b) {
  var was = isOpen('mg' + a + '_' + b), i;
  for (i = 0; i < MENU[a].g.length; i++) { var el = document.getElementById('mg' + a + '_' + i); if (el) { removeClass(el, 'open'); } }
  if (!was) { addClass(document.getElementById('mg' + a + '_' + b), 'open'); }
  saveOpen();
  return false;
}
function msub(a, b, c) {
  var was = isOpen('ms' + a + '_' + b + '_' + c), i, el, g = MENU[a].g[b];
  for (i = 0; i < g.i.length; i++) {
    el = document.getElementById('ms' + a + '_' + b + '_' + i);
    if (el) { removeClass(el, 'open'); }
  }
  if (!was) { addClass(document.getElementById('ms' + a + '_' + b + '_' + c), 'open'); }
  saveOpen();
  return false;
}

/* sabit menude aktif konuyu gorunur alana getir */
function scrollMenuToCur() {
  var box = document.getElementById('sidein'), els, i, li = null, t;
  if (!box) { return; }
  els = box.getElementsByTagName('li');
  for (i = 0; i < els.length; i++) { if (hasClass(els[i], 'cur')) { li = els[i]; break; } }
  if (li) { t = li.offsetTop - 80; box.scrollTop = (t > 0) ? t : 0; }
}

function initMenu(root) {
  var cur, side, box, f, oa = -1, ob = -1, oc = -1, saved, parts, restoreY = 0, doRestore = false, item;
  MENU_ROOT = root || '';
  cur = curFile();
  f = findByFile(cur);

  if (f) { oa = f.a; ob = f.b; oc = f.c; sset('open', oa + ',' + ob + ',' + oc); }
  else {
    saved = sget('open');
    if (saved) {
      parts = saved.split(',');
      oa = parseInt(parts[0], 10); ob = parseInt(parts[1], 10); oc = parseInt(parts[2], 10);
      if (isNaN(oa)) { oa = -1; }
      if (isNaN(ob)) { ob = -1; }
      if (isNaN(oc)) { oc = -1; }
    } else { oa = 0; }
  }

  side = document.getElementById('side');
  if (side) {
    side.innerHTML = '<div class="sidein" id="sidein">' + buildMenu(cur, oa, ob, oc) + '</div>';
    if (hasClass(document.body, 'stick')) { scrollMenuToCur(); }
  }
  box = document.getElementById('resume-box');
  if (box) { box.innerHTML = resumeHtml(cur); }

  if (!f) { return; }   /* ana sayfa: kaldigin yeri degistirme */
  item = f.item;

  /* en son okunan sayfa buysa (menuden, adresten ya da "Kaldigin yer"den), kaldigi yerden ac */
  if (sget('last') === item[1]) {
    restoreY = parseInt(sget('y'), 10) || 0;
    doRestore = restoreY > 100;
  }
  sset('resume', '0');

  /* kayit: ayni sayfada her zaman guncelle; baska sayfada yalniz gercekten okumaya baslayinca (>100 px) devral */
  function save() {
    var y = getY();
    if (sget('last') === item[1]) { sset('y', y); }
    else if (y > 100) { sset('last', item[1]); sset('y', y); }
  }
  function startSaving() {
    setInterval(save, 1500);
    window.onunload = save;
    window.onbeforeunload = save;
  }
  if (doRestore) {
    window.onload = function () {
      setTimeout(function () { try { window.scrollTo(0, restoreY); } catch (e) {} startSaving(); }, 150);
    };
  } else {
    startSaving();
  }
}
